// Build a minimal inchi_Input with 1-4 atoms and no bonds.
int n = (int)(*FUZZ_PARAM(unsigned int) % 4) + 1;
inchi_Atom *atoms = new inchi_Atom[n];
for (int i = 0; i < n; ++i) {
    inchi_Atom &a = atoms[i];
    a.x = 0.0; a.y = 0.0; a.z = 0.0;
    a.num_bonds = 0;
    a.isotopic_mass = 0;
    a.radical = 0;
    a.charge = 0;
    // Safe element symbol; library recognizes "C".
    a.elname[0] = 'C'; a.elname[1] = '\0';
    // Zero neighbor/bond arrays defensively
    for (size_t k = 0; k < sizeof(a.neighbor)/sizeof(a.neighbor[0]); ++k) { a.neighbor[k] = 0; }
    for (size_t k = 0; k < sizeof(a.bond_type)/sizeof(a.bond_type[0]); ++k) { a.bond_type[k] = 0; }
    for (size_t k = 0; k < sizeof(a.bond_stereo)/sizeof(a.bond_stereo[0]); ++k) { a.bond_stereo[k] = 0; }
    for (size_t k = 0; k < sizeof(a.num_iso_H)/sizeof(a.num_iso_H[0]); ++k) { a.num_iso_H[k] = 0; }
}

inchi_Input *inp = new inchi_Input;
inp->atom = atoms;
inp->stereo0D = nullptr;
inp->szOptions = nullptr; // no options
inp->num_atoms = (AT_NUM)n;
inp->num_stereo0D = 0;

// Allocate output holder on heap to persist beyond this stub; per API do not zero-initialize intentionally.
inchi_Output *out = new inchi_Output;

int rc = GetINCHI(inp, out);
// Accept any return (OK/WARNING/ERROR); strings may be allocated even on WARNING/ERROR.
// Attribute records how to free this output.
FUZZ_SET_ATTR_STR(out, "free_kind", "FreeINCHI");
FUZZ_SET_ATTR_INT(out, "status", rc);

// Clean up caller-owned input allocations now; outputs persist.
delete[] atoms;
delete inp;

// Provide out as an output for later FreeINCHI.

// Minimal standard input: 1-3 atoms, no bonds.
int n = (int)(*FUZZ_PARAM(unsigned int) % 3) + 1;
inchi_Atom *atoms = new inchi_Atom[n];
for (int i = 0; i < n; ++i) {
    inchi_Atom &a = atoms[i];
    a.x = 0.0; a.y = 0.0; a.z = 0.0;
    a.num_bonds = 0; a.isotopic_mass = 0; a.radical = 0; a.charge = 0;
    a.elname[0] = 'C'; a.elname[1] = '\0';
    for (size_t k = 0; k < sizeof(a.neighbor)/sizeof(a.neighbor[0]); ++k) { a.neighbor[k] = 0; }
    for (size_t k = 0; k < sizeof(a.bond_type)/sizeof(a.bond_type[0]); ++k) { a.bond_type[k] = 0; }
    for (size_t k = 0; k < sizeof(a.bond_stereo)/sizeof(a.bond_stereo[0]); ++k) { a.bond_stereo[k] = 0; }
    for (size_t k = 0; k < sizeof(a.num_iso_H)/sizeof(a.num_iso_H[0]); ++k) { a.num_iso_H[k] = 0; }
}

inchi_Input *inp = new inchi_Input;
inp->atom = atoms;
inp->stereo0D = nullptr;
// Only standard-allowed options; randomly set one benign option or none.
const char *std_opts[4] = { nullptr, "-NEWPSOFF", "-DoNotAddH", "-SNon" };
int oi = (int)(*FUZZ_PARAM(unsigned int) % 4);
inp->szOptions = (char*)std_opts[oi];
inp->num_atoms = (AT_NUM)n;
inp->num_stereo0D = 0;

inchi_Output *out = new inchi_Output;
int rc = GetStdINCHI(inp, out);
FUZZ_SET_ATTR_STR(out, "free_kind", "FreeStdINCHI");
FUZZ_SET_ATTR_INT(out, "status", rc);

delete[] atoms;
delete inp;

// Return out for later FreeStdINCHI.

// Enforce that this output came from a FreeINCHI-producing API.
const char *fk = FUZZ_GET_ATTR_STR(out, "free_kind");
int is_ok = (fk && fk[0] && strcmp(fk, "FreeINCHI") == 0);
if (!is_ok) { FUZZ_BAIL(); }

// Invoke the free and drop the object (do not return it as an output)
FreeINCHI(out);
// Do not use out after freeing.

// Ensure this output corresponds to a Standard InChI result.
const char *fk = FUZZ_GET_ATTR_STR(out, "free_kind");
int is_ok = (fk && fk[0] && strcmp(fk, "FreeStdINCHI") == 0);
